/* AppAdminAccessMapper.existsNodeAdminAnySite */
SELECT EXISTS(
    SELECT 1
    FROM TB_SITE_NODE
    WHERE CMPNY_CD = #{cmpnyCd}
      AND ( MAIN_ADMIN_CD = #{userCd} OR SUB_ADMIN_CD = #{userCd} )
)

/* AppAdminAccessMapper.existsNodeAdminInSite */
SELECT EXISTS(
    SELECT 1
    FROM TB_SITE_NODE
    WHERE CMPNY_CD = #{cmpnyCd}
      AND SITE_CD = #{siteCd}
      AND ( MAIN_ADMIN_CD = #{userCd} OR SUB_ADMIN_CD = #{userCd} )
)
